module MhpmeventModule(
  input         clock,
  input         reset,
  input         w_wen,
  input  [63:0] w_wdata,
  output [63:0] rdata,
  output        regOut_OF,
  output        regOut_MINH,
  output        regOut_SINH,
  output        regOut_UINH,
  output        regOut_VSINH,
  output        regOut_VUINH,
  output [4:0]  regOut_OPTYPE2,
  output [4:0]  regOut_OPTYPE1,
  output [4:0]  regOut_OPTYPE0,
  output [9:0]  regOut_EVENT3,
  output [9:0]  regOut_EVENT2,
  output [9:0]  regOut_EVENT1,
  output [9:0]  regOut_EVENT0,
  input         ofFromPerfCnt
);

  reg       reg_OF;
  reg       reg_MINH;
  reg       reg_SINH;
  reg       reg_UINH;
  reg       reg_VSINH;
  reg       reg_VUINH;
  reg [4:0] reg_OPTYPE2;
  reg [4:0] reg_OPTYPE1;
  reg [4:0] reg_OPTYPE0;
  reg [9:0] reg_EVENT3;
  reg [9:0] reg_EVENT2;
  reg [9:0] reg_EVENT1;
  reg [9:0] reg_EVENT0;
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      reg_OF <= 1'h0;
      reg_MINH <= 1'h0;
      reg_SINH <= 1'h0;
      reg_UINH <= 1'h0;
      reg_VSINH <= 1'h0;
      reg_VUINH <= 1'h0;
      reg_OPTYPE2 <= 5'h0;
      reg_OPTYPE1 <= 5'h0;
      reg_OPTYPE0 <= 5'h0;
      reg_EVENT3 <= 10'h0;
      reg_EVENT2 <= 10'h0;
      reg_EVENT1 <= 10'h0;
      reg_EVENT0 <= 10'h0;
    end
    else begin
      if (w_wen) begin
        reg_OF <= w_wdata[63];
        reg_MINH <= w_wdata[62];
        reg_SINH <= w_wdata[61];
        reg_UINH <= w_wdata[60];
        reg_VSINH <= w_wdata[59];
        reg_VUINH <= w_wdata[58];
        reg_EVENT3 <= w_wdata[39:30];
        reg_EVENT2 <= w_wdata[29:20];
        reg_EVENT1 <= w_wdata[19:10];
        reg_EVENT0 <= w_wdata[9:0];
      end
      else if (ofFromPerfCnt)
        reg_OF <= ofFromPerfCnt;
      if (w_wen
          & (|{w_wdata[54:50] == 5'h4,
               w_wdata[54:50] == 5'h2,
               w_wdata[54:50] == 5'h1,
               w_wdata[54:50] == 5'h0}))
        reg_OPTYPE2 <= w_wdata[54:50];
      if (w_wen
          & (|{w_wdata[49:45] == 5'h4,
               w_wdata[49:45] == 5'h2,
               w_wdata[49:45] == 5'h1,
               w_wdata[49:45] == 5'h0}))
        reg_OPTYPE1 <= w_wdata[49:45];
      if (w_wen
          & (|{w_wdata[44:40] == 5'h4,
               w_wdata[44:40] == 5'h2,
               w_wdata[44:40] == 5'h1,
               w_wdata[44:40] == 5'h0}))
        reg_OPTYPE0 <= w_wdata[44:40];
    end
  end
  assign rdata =
    {reg_OF,
     reg_MINH,
     reg_SINH,
     reg_UINH,
     reg_VSINH,
     reg_VUINH,
     3'h0,
     reg_OPTYPE2,
     reg_OPTYPE1,
     reg_OPTYPE0,
     reg_EVENT3,
     reg_EVENT2,
     reg_EVENT1,
     reg_EVENT0};
  assign regOut_OF = reg_OF;
  assign regOut_MINH = reg_MINH;
  assign regOut_SINH = reg_SINH;
  assign regOut_UINH = reg_UINH;
  assign regOut_VSINH = reg_VSINH;
  assign regOut_VUINH = reg_VUINH;
  assign regOut_OPTYPE2 = reg_OPTYPE2;
  assign regOut_OPTYPE1 = reg_OPTYPE1;
  assign regOut_OPTYPE0 = reg_OPTYPE0;
  assign regOut_EVENT3 = reg_EVENT3;
  assign regOut_EVENT2 = reg_EVENT2;
  assign regOut_EVENT1 = reg_EVENT1;
  assign regOut_EVENT0 = reg_EVENT0;
endmodule
